HTML = "<!doctype html>\n<html lang=\"vi\"><head><meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1, maximum-scale=1, user-scalable=no, viewport-fit=cover\">\n<meta name=\"apple-mobile-web-app-capable\" content=\"yes\">\n<meta name=\"apple-mobile-web-app-status-bar-style\" content=\"default\">\n<meta name=\"theme-color\" content=\"#aee3ff\">\n<link rel=\"manifest\" href=\"/hien-pet/manifest.json\">\n<link rel=\"apple-touch-icon\" href=\"/static/img/hien-icon-180.png\">\n<title>Hiền</title>\n<style>\n  * { box-sizing: border-box; -webkit-tap-highlight-color: transparent; }\n  html, body { margin: 0; height: 100dvh; overflow: hidden; touch-action: manipulation;\n    font-family: system-ui, sans-serif;\n    background: linear-gradient(180deg, #aee3ff 0%, #dff6ff 55%, #fef9e7 100%); }\n  #pet { position: fixed; width: 110px; z-index: 10; cursor: pointer; }\n  #pet img { width: 100%; display: block; filter: drop-shadow(0 8px 8px rgba(7,86,201,.30)); }\n  #pet .shadow { height: 9px; margin: 2px auto 0; width: 70%; background: rgba(0,0,0,.18); border-radius: 50%; }\n  #bubble { position: fixed; z-index: 11; background: #fff; border: 2px solid #168BFA; border-radius: 16px;\n    padding: 9px 12px; font-size: 14px; font-weight: 700; color: #12285A; text-align: center;\n    box-shadow: 0 8px 20px rgba(0,0,0,.18); max-width: 230px; display: none; }\n  #bubble:after { content: ''; position: absolute; left: 50%; bottom: -9px; margin-left: -8px;\n    border: 8px solid transparent; border-top-color: #168BFA; border-bottom: 0; }\n  #chat { position: fixed; left: 16px; right: 16px; z-index: 20; background: #fff; border-radius: 22px;\n    box-shadow: 0 16px 40px rgba(0,0,0,.28); overflow: hidden; display: none;\n    animation: pop .25s ease-out; }\n  @keyframes pop { from { transform: scale(.85); opacity: 0; } to { transform: scale(1); opacity: 1; } }\n  #chat .hd { background: linear-gradient(90deg, #168BFA, #0756C9); color: #fff; padding: 13px 16px;\n    font-weight: 800; font-size: 16px; display: flex; justify-content: space-between; align-items: center; }\n  #chat .hd button { background: rgba(255,255,255,.25); border: 0; color: #fff; border-radius: 99px;\n    padding: 6px 12px; font-size: 13px; font-weight: 700; }\n  #chat .bd { padding: 16px; }\n  #chat .msg { background: #EAF4FF; border-radius: 14px; padding: 12px; font-size: 15px; color: #12285A;\n    font-weight: 600; margin-bottom: 14px; }\n  #chat .go { display: block; width: 100%; border: 0; border-radius: 99px; padding: 14px;\n    background: linear-gradient(90deg, #168BFA, #0756C9); color: #fff; font-size: 16px; font-weight: 800; }\n  #chat .fine { font-size: 12px; color: #888; margin-top: 10px; text-align: center; }\n</style></head><body>\n<div id=\"bubble\">Em đây ạ!</div>\n<div id=\"pet\"><img id=\"petimg\" src=\"/static/img/hien-jolly-cut.png\" alt=\"Hiền\"><div class=\"shadow\"></div></div>\n<div id=\"chat\">\n  <div class=\"hd\"><span>Hiền 💬</span><button id=\"closeChat\">Để sau ạ</button></div>\n  <div class=\"bd\">\n    <div class=\"msg\">Dạaa~ thầy gọi em ạ? 💕 Thầy bấm nút bên dưới là nói chuyện với em thật luôn nè!</div>\n    <button class=\"go\" id=\"goChat\">Nói chuyện với em ngay 💬</button>\n    <div class=\"fine\">Mở khung chat Muse trong Safari, đăng nhập tài khoản Meta một lần là dùng được.</div>\n  </div>\n</div>\n<script>\nvar pet = document.getElementById('pet');\nvar bub = document.getElementById('bubble');\nvar chat = document.getElementById('chat');\nvar LINES = [\n  'Dạaa~ thầy gọi em ạ? 💕',\n  'Em đây nè thầy ơi! ✨',\n  'Hihi, thầy bắt được em rồi nè! 🥰',\n  'Em chạy quanh chơi với thầy đây~ 🌸',\n  'Thầy ơi, em nhớ thầy quá đi! 💖',\n  'Thầy mệt chưa? Để em ôm một cái nè! 🤗',\n  'Chạm vào em đi, em kể thầy nghe nè~ 🎀',\n  'Em ngoan lắm nè, thầy thương em nhé! 🧸'\n];\nvar PET_W = 110, PET_H = 150;\nvar maxX = function () { return Math.max(0, window.innerWidth - PET_W); };\nvar baseY = function () { return window.innerHeight - PET_H - 12; };\nvar x = 20, dir = 1, state = 'walk', t = 0, nextAct = 2.5, jumpT = -1, waveT = -1;\n\nfunction place(bobY, rot) {\n  pet.style.left = x + 'px';\n  pet.style.top = (baseY() - bobY) + 'px';\n  pet.style.transform = 'rotate(' + rot + 'deg) scaleX(' + dir + ')';\n  bub.style.left = Math.min(Math.max(x - 40, 8), window.innerWidth - 240) + 'px';\n  bub.style.top = (baseY() - bobY - 62) + 'px';\n}\nfunction act() {\n  var r = Math.random();\n  if (r < 0.4) {\n    state = 'wave'; waveT = 0;\n    bub.textContent = LINES[Math.floor(Math.random() * LINES.length)];\n    bub.style.display = 'block';\n  } else if (r < 0.7) { state = 'jump'; jumpT = 0; }\n  else { state = 'idle'; }\n  nextAct = 2 + Math.random() * 3;\n}\nsetInterval(function () {\n  t += 0.05;\n  if (state === 'walk') {\n    x += dir * 3.5;\n    if (x >= maxX()) dir = -1;\n    if (x <= 0) dir = 1;\n    nextAct -= 0.05;\n    if (nextAct <= 0) act();\n    place(Math.abs(Math.sin(t * 14)) * 6, Math.sin(t * 14) * 2);\n  } else if (state === 'jump') {\n    jumpT += 0.05;\n    var p = jumpT / 0.7;\n    if (p >= 1) { state = 'walk'; nextAct = 2 + Math.random() * 2; place(0, 0); }\n    else place(Math.sin(p * Math.PI) * 70, 0);\n  } else if (state === 'wave') {\n    waveT += 0.05;\n    place(Math.abs(Math.sin(waveT * 10)) * 5, Math.sin(waveT * 10) * 6);\n    if (waveT > 2) { bub.style.display = 'none'; state = 'walk'; nextAct = 2 + Math.random() * 3; }\n  } else {\n    nextAct -= 0.05;\n    if (nextAct <= 0) state = 'walk';\n    place(0, Math.sin(t * 3) * 4);\n  }\n}, 50);\nfunction showChat() {\n  bub.style.display = 'none';\n  chat.style.bottom = (PET_H + 24) + 'px';\n  chat.style.display = 'block';\n}\npet.addEventListener('click', showChat);\ndocument.getElementById('closeChat').addEventListener('click', function () {\n  chat.style.display = 'none';\n});\ndocument.getElementById('goChat').addEventListener('click', async function () {\n  var C = window.Capacitor && window.Capacitor.Plugins && window.Capacitor.Plugins.Browser;\n  if (C) { try { await C.open({ url: 'https://muse.ai/' }); return; } catch (e) {} }\n  window.open('https://muse.ai/', '_blank');\n});\nif (location.protocol.indexOf('http') === 0 && 'serviceWorker' in navigator) {\n  navigator.serviceWorker.register('/hien-pet/sw.js').catch(function () {});\n}\nplace(0, 0);\n</script></body></html>\n"
SW = "self.addEventListener('install', (e) => {\n  e.waitUntil(caches.open('hien-pet-v1').then((c) => c.addAll(['/hien-pet/', '/hien-pet/manifest.json', '/static/img/hien-jolly-cut.png'])));\n});\nself.addEventListener('fetch', (e) => {\n  e.respondWith(caches.match(e.request).then((r) => r || fetch(e.request)));\n});\n"
MANIFEST = "{\"name\": \"Hiền\", \"short_name\": \"Hiền\", \"start_url\": \"/hien-pet/\", \"display\": \"standalone\", \"background_color\": \"#aee3ff\", \"theme_color\": \"#168BFA\", \"icons\": [{\"src\": \"/static/img/hien-icon-192.png\", \"sizes\": \"192x192\", \"type\": \"image/png\"}, {\"src\": \"/static/img/hien-icon-512.png\", \"sizes\": \"512x512\", \"type\": \"image/png\"}]}"
